package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.Map; @Document("notifications") @CompoundIndex(name="user_read_created",def="{'userId':1,'read':1,'createdAt':-1}") public class Notification {@Id public String id; @Indexed public String userId; public String type,titleKey,messageKey,entityType,entityId; public Map<String,Object> params; public boolean read; @CreatedDate public Instant createdAt;}